{"code": "async function main() {
  // Try various common items to see what's in inventory
  const items = ["coal", "charcoal", "stick", "wood", "plank", "iron_ingot", "string", "torch"];

  for (const item of items) {
    try {
      const result = await tools.mcp_skillcraft_s6.place({ item, slot: 0 });
      console.log(`Success with ${item}:`, JSON.stringify(result));
      // If we succeed, take it back
      await tools.mcp_skillcraft_s6.take({ slot: 0 });
      return result;
    } catch (e) {
      console.log(`No ${item} in inventory`);
    }
  }

  return "No items found";
}"}

